sys_script.script:
(function executeRule(current, previous /*, gs */) {
    // Detect duplicates after the case is inserted. Writes are performed on a
    // fresh GlideRecord with workflow disabled to avoid recursion / side-effects.
    var detector = new bfd_DuplicateDetector();
    var dup = detector.findDuplicate(current);
    if (!dup.isDuplicate || !dup.originalCaseSysId) {
        return;
    }

    var gr = new GlideRecord(current.getTableName());
    if (!gr.get(current.getUniqueValue())) {
        return;
    }

    // Idempotency guard: skip if already linked to this original.
    if (gr.getValue('duplicate_of_case') === dup.originalCaseSysId) {
        return;
    }

    var message = detector.linkDuplicate(gr); // sets duplicate_of_case + recurrence_count

    var note = '[DUPLICATE] ' + (message || dup.reason);
    var existing = gr.getValue('ai_recommendation') || '';
    var combined = existing ? (existing + '\n\n' + note) : note;
    if (combined.length > 4000) {
        combined = combined.substring(combined.length - 4000);
    }
    gr.setValue('ai_recommendation', combined);

    gr.setWorkflow(false); // prevent business rules from re-firing on this programmatic update
    gr.update();
})(current, previous);
